// Health section: the Health page (Alerts, Checks, Doctor), the Doctor tab and the synthetic-check pills of the node
// page, the fix dialog, and every sentence the server names by key. English is the source of truth: `ru` is
// type-checked against it. The panel never sends prose: it sends keys that are resolved here (proto
// "health.proto", service comment): alert titles "health.alert.<kind>.title", reasons "health.alert.<kind>.why[.<variant>]",
// doctor rows "doctor.<check>.title" and "health.doctor.<check>.why[.<hint>]", fix buttons and plans
// "health.fix.<fix>.label|plan", check errors "health.check.err.<code>". A key the dictionary lacks is shown as the
// key itself (titles) or left out (explanations), so a newer panel with this SPA degrades to readable text.
// Our own UI strings are "hl.*". "a|b" is a plural (one|other in English, one|few|many in Russian); {name} is a placeholder.
// The admin speaks to the owner informally («ты»).
