  "health.doctor.disk_space.why": "{mount} 已用 {used_pct}%，剩余 {free_mb} MB。磁盘写满会使日志、证书续期和 Agent 本身停止工作。如果大头是日志，修复操作会清理它；否则请手动释放空间。",
  "health.doctor.journald_size.why": "系统日志占用 {journal_mb} MB，而上限是 {cap_mb} MB，说明上限没有生效。清理是安全的，只会丢失旧的日志行。",
  "health.doctor.security_updates.why": "没有自动安全更新时，OpenSSH、OpenSSL 或内核中已修复的漏洞会一直留在这台服务器上，直到有人登录并运行 apt。unattended-upgrades 每天从服务器自己的 apt 源安装安全修复，不会自行重启服务器。如果这台服务器用其他方式更新，请将此项标记为正常。",
  "health.doctor.unit_generation.why": "Agent 通过一个 systemd 单元运行，该单元设定了沙箱、内存限制，以及在自更新反复崩溃时回滚的保护。第 {unit_gen} 版的单元缺少其中一部分；刷新会用 Agent 自身二进制文件内置的模板写入第 {current} 版。",
  "health.doctor.dstate_tasks.why": "挂起的进程：{stuck}（{tasks}），在等待硬件。这样的主机很快就会不再响应 SSH 和 apt。节点上无法修复：请在服务商控制面板中重启它。",
  "health.doctor.dstate_tasks.why.qxl_ttm": "内核日志显示 QXL/TTM 显卡驱动卡死（某些服务商的虚拟机上会出现）。它会阻塞 apt 和 SSH 登录。只有在服务商控制面板中重启才有用。",
  "health.doctor.time_sync.why": "时钟与面板相差 {offset_s} 秒（NTP 已同步：{ntp_synced}）。时钟不准会导致证书、TOTP 验证码和 WireGuard 握手出错。请在主机上开启 NTP：timedatectl set-ntp true。",
  "health.doctor.resolver.why": "服务器自己的 DNS 解析器对 {failed} 解析失败，或响应很慢（{median_ms} ms）。apt、证书续期和 WARP 出口都依赖它。在俄罗斯的节点上，公共解析器还会让 gosuslugi.ru 无法访问，因此修复会在那里选用 Yandex DNS。用户流量使用的 DNS 在节点设置中配置。",
  "health.doctor.ipv6.why": "此主机上的 IPv6：{ipv6}；出站 IPv6 连接：{connect}。无法连通的 IPv6 地址会让带有 IPv6 记录的网站卡住。关闭客户端 IPv6 后，应用会立即改用 IPv4。",
  "health.doctor.foreign_vpn.why": "此主机上有其他 VPN 软件的残留：{names}。它们可能占用我们的端口或改写流量。面板不会删除它们：请手动决定。",
  "health.doctor.foreign_nft.why": "不属于 Mistgate 的防火墙表：{tables}。曾有一次，其中一张表里被遗忘的重定向让整个节点瘫痪。请用 nft list ruleset 查看，并移除不需要的内容。",
  "health.doctor.port_conflicts.why": "有 Mistgate 以外的程序占用了某个协议配置所需的端口，导致该协议配置无法启动或已损坏。如果端口现在已空闲，重启该协议配置即可；否则请停止另一个进程，或把协议配置换到其他端口。",
  "health.doctor.net_baseline.why": "节点的网络调优与基线不同（fq + BBR、QUIC 所需的 UDP 缓冲区和日志上限）：{differs}。修复操作会重新设置，并且只改动 Mistgate 自己的文件。",
  "health.doctor.cert_expiry.why": "此节点上的某个证书需要关注（{reason}，剩余 {days_left} 天）。ACME 证书会提前一个月自动续期，所以剩余时间太少说明续期失败：请确认域名指向该节点，且端口 80 和 443 可以访问。自签名证书重启其协议配置即可重新生成。",
  "health.doctor.memory_pressure.why": "可用内存 {avail_pct}%，交换分区已用 {swap_pct}%，24 小时内 OOM 终止进程 {oom_kills} 次。内存耗尽时内核会终止进程，可能终止 Agent 或 VPN 引擎。请把用户迁到其他节点，或换更大的服务器。",
  "health.doctor.cpu_softirq.why": "10 分钟内，网络中断占用 {softirq_pct}% 的 CPU（全部 CPU：{cpu_pct}%）。小型虚拟服务器上繁忙的 VPN 节点到达上限时就是这样：速度会最先下降。请把用户分散到其他节点。",
  "health.doctor.cpu_steal.why": "10 分钟内，虚拟化层把这台服务器 {steal_pct}% 的 CPU 时间分给了同一宿主机上的其他虚拟机（峰值 {steal_max_pct}%）。服务商超卖了宿主机的 CPU，节点本身无法解决：用户会感到连接变慢、延迟抖动。请让服务商把服务器迁到更空闲的宿主机，或把节点换到其他服务商。",
  "health.doctor.conntrack_fill.why": "内核连接跟踪表已用 {count} / {max} 条（{fill_pct}%）。表满时内核会丢弃所有新连接，之后连接的人都会觉得节点挂了。请在服务器上调大 net.netfilter.nf_conntrack_max，或把用户迁到其他节点。",
  "health.doctor.agent_fds.why": "Agent 打开了 {fds} / {limit} 个文件（{used_pct}%），每个协议配置的每条连接都占一个。到达上限后新连接会失败，而节点看起来仍然在线。Mistgate 服务允许 65536 个：如果 Agent 是手动启动的，请改为以服务方式运行；否则请把用户迁到其他节点。",
  "health.doctor.kernel_headers.why": "已请求 AmneziaWG 内核模式，但内核 {kernel} 缺少模块所需的：{missing}。下面的命令会安装它们并构建模块；也可以把节点的 AmneziaWG 后端设为自动：用户态后端不需要这些。",
  "hl.doctor.runCommand": "以 root 身份在节点上运行：",

